def decision_subterms(value):
    out=[]
    todo=[value]
    while todo:
        item=todo.pop()
        if isinstance(item,list) and item:
            out.append(item)
            i=1
            while i<len(item):
                if isinstance(item[i],list):
                    todo.append(item[i])
                i+=1
    return out

def decision_has(value,name):
    for item in decision_subterms(value):
        if item[0]==name:
            return True
    return False

def decision_unique(values):
    out=[]
    for value in values:
        if value not in out:
            out.append(value)
    return out

def decision_entries(premises):
    nodes=premises.get('nodes',[])
    roots=premises.get('roots',[])
    by_id={}
    for node in nodes:
        if isinstance(node,dict):
            by_id[node.get('id')]=node
    out=[]
    for root in roots:
        todo=[root]
        seen=set()
        while todo:
            node_id=todo.pop()
            if node_id in seen or node_id not in by_id:
                continue
            seen.add(node_id)
            node=by_id[node_id]
            term=node.get('term')
            if isinstance(term,list) and term:
                out.append([term,root])
            for child in node.get('child_ids',[]):
                todo.append(child)
    return out

def decision_role_tags(value,definitions):
    tags=set()
    todo=[value]
    expanded=set()
    while todo:
        item=todo.pop()
        if not isinstance(item,list) or not item:
            continue
        name=item[0]
        if name=='representatives_of' and len(item)>1:
            key=str(item[1])
            if key not in expanded:
                expanded.add(key)
                for owner,members in definitions:
                    if str(owner)==key or (isinstance(owner,list) and owner and owner and owner[0]=='party'):
                        todo.append(members)
            continue
        if name in ('employees_of','internal_personnel_of') and len(item)>1:
            if decision_has(item[1],'controlled_entities_of') or decision_has(item[1],'affiliates_of'):
                tags.add('controlled_employees')
            else:
                tags.add('employees')
        elif name in ('independent_contractors_of','consultants_of','agents_of','professional_advisors_of','legal_advisors_of','financial_advisors_of','accountants_of','lenders_of'):
            tags.add('professionals')
        elif name=='third_parties':
            tags.add('third_parties')
        i=1
        while i<len(item):
            if isinstance(item[i],list):
                todo.append(item[i])
            i+=1
    return tags

def decision_full_material(value):
    for item in decision_subterms(value):
        if item[0]=='source_bounded_material' and len(item)>1:
            base=item[1]
            if isinstance(base,list) and base:
                if base[0] in ('confidential_information','information_bundle','source_stated_materials'):
                    return True
                if base[0]=='copies_of':
                    continue
        if item[0]=='information_bundle':
            return True
        if item[0]=='confidential_information' and not decision_has(value,'source_bounded_material'):
            return True
    return False

def apply(inputs,premises):
    task=inputs.get('task_id')
    if task not in ('nda-5','nda-7','nda-16','nda-20'):
        return {'handled':False,'answer':None,'used_nodes':[]}
    entries=decision_entries(premises)
    definitions=[]
    definition_roots=[]
    permissions=[]
    prohibitions=[]
    disposals=[]
    retention_permissions=[]
    retention_prohibitions=[]
    disclosure_absence=[]
    disposal_absence=[]
    for term,root in entries:
        if term[0]=='define_representative' and len(term)==3:
            definitions.append([term[1],term[2]])
            definition_roots.append(root)
        elif term[0]=='complete_source_no_disclosure_permission':
            disclosure_absence.append(root)
        elif term[0]=='complete_source_no_disposal_obligation':
            disposal_absence.append(root)
        elif term[0]=='disposal_obligation' and len(term)==5:
            disposals.append([term,root])
        elif term[0] in ('retention_permission','retention_exception'):
            retention_permissions.append(root)
        elif term[0] in ('retention_prohibition','absolute_retention_prohibition'):
            retention_prohibitions.append(root)
    for term,root in entries:
        if term[0] not in ('permission','prohibition') or len(term)<3:
            continue
        action=term[2]
        if not isinstance(action,list) or len(action)!=3 or action[0]!='disclose' or not decision_has(action[1],'confidential_information'):
            continue
        item=[root,decision_role_tags(action[2],definitions),action[2]]
        if term[0]=='permission':
            permissions.append(item)
        else:
            prohibitions.append(item)
    if task in ('nda-5','nda-7'):
        relevant=[]
        for root,tags,recipient in permissions:
            relevant.append(root)
            if task=='nda-5' and 'employees' in tags:
                used=[root]
                if decision_has(recipient,'representatives_of'):
                    used.extend(definition_roots)
                return {'handled':True,'answer':'Entailment','used_nodes':decision_unique(used)}
            if task=='nda-7' and tags.intersection({'professionals','third_parties'}):
                used=[root]
                if decision_has(recipient,'representatives_of'):
                    used.extend(definition_roots)
                return {'handled':True,'answer':'Entailment','used_nodes':decision_unique(used)}
        for root,tags,recipient in prohibitions:
            relevant.append(root)
            if decision_has(recipient,'outsiders_to'):
                continue
            if task=='nda-5' and 'employees' in tags:
                return {'handled':True,'answer':'Contradiction','used_nodes':[root]}
            if task=='nda-7' and tags.intersection({'professionals','third_parties'}):
                return {'handled':True,'answer':'Contradiction','used_nodes':[root]}
        if relevant or disclosure_absence:
            return {'handled':True,'answer':'NotMentioned','used_nodes':decision_unique(relevant+definition_roots+disclosure_absence)}
        return {'handled':False,'answer':None,'used_nodes':[]}
    if task=='nda-16':
        endpoint=[]
        relevant=[]
        for term,root in disposals:
            if decision_has(term[2],'return_to') or decision_has(term[2],'destroy'):
                relevant.append(root)
                for name in ('agreement_termination','project_termination','relationship_termination','service_termination','relationship_nonformation_deadline','purpose_completion'):
                    if decision_has(term[3],name):
                        endpoint.append(root)
        if endpoint:
            return {'handled':True,'answer':'Entailment','used_nodes':decision_unique(endpoint)}
        if relevant or disposal_absence:
            return {'handled':True,'answer':'NotMentioned','used_nodes':decision_unique(relevant+disposal_absence)}
        return {'handled':False,'answer':None,'used_nodes':[]}
    if retention_permissions:
        return {'handled':True,'answer':'Entailment','used_nodes':decision_unique(retention_permissions)}
    if retention_prohibitions:
        return {'handled':True,'answer':'Contradiction','used_nodes':decision_unique(retention_prohibitions)}
    full=[]
    relevant=[]
    for term,root in disposals:
        if decision_has(term[2],'return_to') or decision_has(term[2],'destroy'):
            relevant.append(root)
            if decision_full_material(term[2]):
                full.append(root)
    if full:
        return {'handled':True,'answer':'Contradiction','used_nodes':decision_unique(full)}
    if relevant or disposal_absence:
        return {'handled':True,'answer':'NotMentioned','used_nodes':decision_unique(relevant+disposal_absence)}
    return {'handled':False,'answer':None,'used_nodes':[]}
